'use strict';

// MODULES //

var processBlock = require( './process_block.js' );


// MAIN //

/**
* Extracts example blocks from a Markdown file.
*
* @private
* @param {string} src - source string
* @param {string} file - file path
* @returns {Array<Object>} blocks
*
* @example
* var src = '```c\\nint x = 0;\\n```';
* extractMarkdown( src, '/path/to/file.md' );
*/
function extractMarkdown( src, file ) {
	var inExamplesSection;
	var isFuncSignature;
	var hasPlaceholders;
	var isOnlyIncludes;
	var inUsageSection;
	var blockLines;
	var inCSection;
	var skipBlock;
	var inFenced;
	var blocks;
	var lines;
	var line;
	var text;
	var i;
	var j;
	var k;

	blocks = [];
	lines = src.split( '\n' );
	inFenced = false;
	inCSection = false;
	inExamplesSection = false;
	inUsageSection = false;
	blockLines = [];
	skipBlock = false;

	for ( i = 0; i < lines.length; i++ ) {
		line = lines[ i ];

		if ( /<section class="c">/.test( line ) ) {
			inCSection = true;
		}
		if ( /<section class="examples">/.test( line ) ) {
			inExamplesSection = true;
		}
		if ( /<section class="usage">/.test( line ) ) {
			inUsageSection = true;
		}
		if ( /<\/section>/.test( line ) ) {
			if ( inExamplesSection ) {
				inExamplesSection = false;
			} else if ( inUsageSection ) {
				inUsageSection = false;
			} else if ( inCSection ) {
				inCSection = false;
			}
		}

		if ( inFenced ) {
			if ( /^```$/.test( line ) ) {
				inFenced = false;

				// Additional heuristic skips based on block content:
				isOnlyIncludes = true;
				isFuncSignature = (
					blockLines.length === 1 &&
					/;\s*$/.test( blockLines[ 0 ].text ) &&
					/\(.*\)/.test( blockLines[ 0 ].text ) &&
					!/[=]/.test( blockLines[ 0 ].text )
				);
				hasPlaceholders = false;

				for ( j = 0; j < blockLines.length; j++ ) {
					text = blockLines[ j ].text;
					if ( !/^\s*#include\b/.test( text ) && !/^\s*$/.test( text ) ) {
						isOnlyIncludes = false;
					}
					if ( /\.\.\./.test( text ) || /…/.test( text ) ) {
						hasPlaceholders = true;
					}
				}

				if ( isOnlyIncludes || isFuncSignature || hasPlaceholders ) {
					skipBlock = true;
				}

				if ( !skipBlock ) {
					blocks.push(processBlock( blockLines, file, blocks.length ));
				}
			} else {
				blockLines.push({
					'text': line,
					'line': i + 1
				});
			}
		} else if ( /^```c\b/.test( line ) ) {
			skipBlock = false;
			if ( i > 0 ) {
				k = i - 1;
				while ( k >= 0 && /^\s*$/.test( lines[ k ] ) ) {
					k -= 1;
				}
				if ( k >= 0 && /<!--\s*run-disable\s*-->/.test( lines[ k ] ) ) {
					skipBlock = true;
				}
			}
			if ( !inCSection && !inExamplesSection && !inUsageSection ) {
				skipBlock = true;
			}
			inFenced = true;
			blockLines = [];
		}
	}

	return blocks;
}


// EXPORTS //

module.exports = extractMarkdown;
